class Stock:
    def __init__(self):
        self.items = {}

    def add(self, sku, qty):
        self.items[sku] = self.items.get(sku, 0) + qty

    def remove(self, sku, qty):
        self.items[sku] = self.items.get(sku, 0) - qty

    def count(self, sku):
        return self.items.get(sku, 0)

from textstats.count import word_count


def test_simple():
    assert word_count('a b c') == 3

def words(text):
    return text.split(' ')


def word_count(text):
    return len(words(text))


def longest(text):
    return max(words(text), key=len)

def parse(text):
    result = {}
    for line in text.splitlines():
        key, value = line.split('=')
        result[key] = value
    return result

from confparse.parse import parse


def test_pairs():
    assert parse('a=1\nb=2') == {'a': '1', 'b': '2'}

class JobQueue:
    def __init__(self):
        self.jobs = []

    def push(self, name, priority):
        self.jobs.append((priority, name))

    def pop(self):
        self.jobs.sort()
        return self.jobs.pop(0)[1]

    def __len__(self):
        return len(self.jobs)

class Book:
    def __init__(self):
        self.entries = []

    def post(self, debit, credit, amount):
        self.entries.append((debit, credit, amount))

    def balance(self, account):
        total = 0
        for debit, credit, amount in self.entries:
            if debit == account:
                total += amount
            if credit == account:
                total -= amount
        return total
